<?php namespace App\Policies; use App\Models\Stall; use App\Models\User; class StallPolicy { public function viewAny(User $user): bool { return true; } public function view(User $user, Stall $stall): bool { return $user->role === 'admin' || $user->id === $stall->user_id; } public function create(User $user): bool { return $user->role === 'admin'; } public function update(User $user, Stall $stall): bool { return $user->role === 'admin' || ($user->role === 'vendor' && $user->id === $stall->user_id); } public function delete(User $user, Stall $stall): bool { return $user->role === 'admin'; } }